   672              uint64_t chansz = ((curc->pixel_type == EXR_PIXEL_HALF) ? 2 : 4);
   673              chansz *= ((uint64_t) width);
   674              if (curc->x_sampling > 1) chansz /= ((uint64_t) curc->x_sampling);
   675              chansz *= ((uint64_t) height);
   676              if (curc->y_sampling > 1)
   677              {
   678                  if (height > 1)
   679                  {
   680                      if (curc->y_sampling > height)
   681                          chansz /= ((uint64_t) height);
   682                      else
   683                          chansz /= ((uint64_t) curc->y_sampling);
   684                  }
   685                  else if ((y % ((int) curc->y_sampling)) != 0)
   686                      chansz = 0;
   687              }
   688              unpacksize += chansz;
   689          }
   690      }
   691      else
   692          unpacksize = part->unpacked_size_per_chunk;
   693      return unpacksize;
   694  }
