  1208  bool
  1209  readCoreScanlinePart (
  1210      exr_context_t f, int part, bool reduceMemory, bool reduceTime)
  1211  {
  1212      exr_result_t     rv;
  1213      exr_attr_box2i_t datawin;
  1214      rv = exr_get_data_window (f, part, &datawin);
  1215      if (rv != EXR_ERR_SUCCESS) return true;
  1216
  1217      uint64_t width =
  1218          (uint64_t) ((int64_t) datawin.max.x - (int64_t) datawin.min.x + 1);
  1219      uint64_t height =
  1220          (uint64_t) ((int64_t) datawin.max.y - (int64_t) datawin.min.y + 1);
  1221
  1222      std::vector<uint8_t>  imgdata;
  1223      bool                  doread = false;
  1224      exr_chunk_info_t      cinfo;
  1225      exr_decode_pipeline_t decoder = EXR_DECODE_PIPELINE_INITIALIZER;
  1226
  1227      int32_t lines_per_chunk;
  1228      rv = exr_get_scanlines_per_chunk (f, part, &lines_per_chunk);
  1229      if (rv != EXR_ERR_SUCCESS) return true;
  1230
  1231      for (uint64_t chunk = 0; chunk < height; chunk += lines_per_chunk)
  1232      {
  1233          exr_chunk_info_t cinfo = {0};
  1234          int              y     = ((int) chunk) + datawin.min.y;
  1235
  1236          rv = exr_read_scanline_chunk_info (f, part, y, &cinfo);
  1237          if (rv != EXR_ERR_SUCCESS)
  1238          {
  1239              if (reduceTime) break;
  1240              continue;
  1241          }
  1242
  1243          if (decoder.channels == NULL)
  1244          {
  1245              rv = exr_decoding_initialize (f, part, &cinfo, &decoder);
  1246              if (rv != EXR_ERR_SUCCESS) break;
  1247
  1248              uint64_t bytes = 0;
  1249              for (int c = 0; c < decoder.channel_count; c++)
  1250              {
  1251                  exr_coding_channel_info_t& outc = decoder.channels[c];
  1252                  // fake addr for default routines
  1253                  outc.decode_to_ptr     = (uint8_t*) 0x1000;
  1254                  outc.user_pixel_stride = outc.user_bytes_per_element;
  1255                  outc.user_line_stride  = outc.user_pixel_stride * width;
  1256                  bytes += width * (uint64_t) outc.user_bytes_per_element *
  1257                           (uint64_t) lines_per_chunk;
  1258              }
  1259
  1260              // TODO: check we are supposed to multiple by lines per chunk above
  1261              doread = true;
  1262              if (reduceMemory && bytes >= gMaxBytesPerScanline) doread = false;
  1263
  1264              if (doread) imgdata.resize (bytes);
  1265              rv = exr_decoding_choose_default_routines (f, part, &decoder);
  1266              if (rv != EXR_ERR_SUCCESS) break;
  1267          }
  1268          else
  1269          {
  1270              rv = exr_decoding_update (f, part, &cinfo, &decoder);
  1271              if (rv != EXR_ERR_SUCCESS)
  1272              {
  1273                  if (reduceTime) break;
  1274                  continue;
  1275              }
  1276          }
  1277
  1278          if (doread)
  1279          {
  1280              uint8_t* dptr = &(imgdata[0]);
  1281              for (int c = 0; c < decoder.channel_count; c++)
  1282              {
  1283                  exr_coding_channel_info_t& outc = decoder.channels[c];
  1284                  outc.decode_to_ptr              = dptr;
  1285                  outc.user_pixel_stride          = outc.user_bytes_per_element;
  1286                  outc.user_line_stride = outc.user_pixel_stride * width;
  1287                  dptr += width * (uint64_t) outc.user_bytes_per_element *
  1288                          (uint64_t) lines_per_chunk;
  1289              }
  1290
  1291              rv = exr_decoding_run (f, part, &decoder);
  1292              if (rv != EXR_ERR_SUCCESS)
  1293              {
  1294                  if (reduceTime) break;
  1295              }
  1296          }
  1297      }
  1298
  1299      exr_decoding_destroy (f, &decoder);
  1300
  1301      return (rv != EXR_ERR_SUCCESS);
  1302  }
